; File: unitedFiles.asm
; ==================================================================
; Mideas MSX2 SCREEN 5 presentation backend
; Project: presentacion_naves_galaxian_rtype_screen5_png_test
; Presentation: Presentation Naves Galaxian R-Type PNG Test
; Screen mode: SCREEN 5 (Graphics III)
; Backend: msx2-screen5-presentation
; MSX2_GAMEFLOW_PRESENT: yes
; MSX2_GAMEFLOW_ASSET: Main MSX2
; MSX2_GAMEFLOW_START_NODE: asset_presentacion_naves_galaxian_rtype_screen5_png_test_msx2_gameflow_start
; MSX2_GAMEFLOW_SCREEN5_NODE: asset_presentacion_naves_galaxian_rtype_screen5_png_test_msx2_gameflow_screen5
; MSX2_GAMEFLOW_PRESENTATION_ASSET_ID: asset_presentacion_naves_galaxian_rtype_screen5_png_test
; MSX2_GAMEFLOW_INITIAL_GLOBALS: 0
; MSX2_GAMEFLOW_AFTER_PRESENTATION_GLOBALS: 0
; MSX2_GAMEFLOW_AFTER_PRE_TEXT_TRANSITION_GLOBALS: 0
; MSX2_GAMEFLOW_AFTER_TRANSITION_GLOBALS: 0
; MSX2_GAMEFLOW_TEXT: none
; MSX2_GAMEFLOW_IFTHENELSE: none
; MSX2_GAMEFLOW_PRE_TEXT_TRANSITION: none
; MSX2_GAMEFLOW_NEXT_TRANSITION: asset_presentacion_naves_galaxian_rtype_screen5_png_test_msx2_gameflow_transition
; MSX2_GAMEFLOW_TERMINAL_ACTION: loop
; MSX2_GAMEFLOW_TRANSITION_EFFECT: fade_to_black
; MSX2_GAMEFLOW_TRANSITION_DURATION_FRAMES: 30
; ROM mode requested: simple32k
; ROM Mode: simple32k
; Mapper Target: konami
; SCREEN5_PRESENTATION_COMPRESSION: ZX0
; SCREEN5_PRESENTATION_CHUNK_LINES: 32
; ==================================================================

CHGMOD  EQU #005F
DISSCR  EQU #0041
ENASCR  EQU #0044
LDIRVM  EQU #005C
FILVRM  EQU #0056
CHGET   EQU #009F
POSIT   EQU #00C6
GRPPRT  EQU #0089
WRTVDP  EQU #0047
RSLREG  EQU #0138
ENASLT  EQU #0024
FORCLR  EQU #F3E8
BAKCLR  EQU #F3E9
BDRCLR  EQU #F3EA
VDP_PALETTE_PORT EQU #9A
SCREEN5_PRESENTATION_ZX0_BUFFER EQU #D000


    org #4000

    db "AB"
    dw init_rom
    dw 0
    dw 0
    dw 0
    dw 0
    dw 0
    dw 0

init_rom:
    di
    call map_page2_to_cart_primary
    call msx2_gameflow_apply_initial_globals
    call DISSCR
    ld a, 5
    call CHGMOD
    ld bc, #0007
    call WRTVDP
    call load_screen5_palette
    call upload_screen5_presentation_bitmap
    call ENASCR
    ei
.main_loop:
    call CHGET
    jp msx2_gameflow_run_transition

map_page2_to_cart_primary:
    ; Map #8000-#BFFF to the same primary/expanded slot as cart page #4000.
    call RSLREG
    rrca
    rrca
    call get_cart_slot_value
    ld h, #80
    jp ENASLT

get_cart_slot_value:
    and #03
    ld c, a
    ld b, 0
    ld hl, #FCC1
    add hl, bc
    ld a, (hl)
    and #80
    jr z, .slot_ready
    or c
    ld c, a
    inc hl
    inc hl
    inc hl
    inc hl
    ld a, (hl)
    and #0C
.slot_ready:
    or c
    ret








msx2_gameflow_run_transition:
    call load_screen5_black_palette
    ld b, #1E
msx2_gameflow_run_transition_transition_wait:
    halt
    djnz msx2_gameflow_run_transition_transition_wait
.gameflow_end_loop_msx2_gameflow_run_transition:
    halt
    jp .gameflow_end_loop_msx2_gameflow_run_transition


clear_screen5_visible_vram:
    ; Terminal clear helper. Clobbers AF, BC, HL.
    xor a
    ld hl, #0000
    ld bc, SCREEN5_PRESENTATION_BITMAP_SIZE
    call FILVRM
    ret


load_screen5_black_palette:
    ; Terminal transition helper. Clobbers AF, BC, HL.
    ld bc, #0010
    call WRTVDP
    ld hl, screen5_black_palette_data
    ld b, 32
.black_palette_loop:
    ld a, (hl)
    out (VDP_PALETTE_PORT), a
    inc hl
    djnz .black_palette_loop
    ret


clear_screen5_vertical_pixel_wipe:
    ; Wipes SCREEN 5 bitmap in 4-pixel vertical steps. Clobbers AF, BC, DE, HL.
    ld e, 0
.vertical_column_loop:
    call clear_screen5_vertical_pixel_column
    inc e
    ld a, e
    cp SCREEN5_PRESENTATION_BYTES_PER_LINE
    jp nc, .vertical_wipe_done
    call clear_screen5_vertical_pixel_column
    inc e
    halt
    ld a, e
    cp SCREEN5_PRESENTATION_BYTES_PER_LINE
    jp c, .vertical_column_loop
.vertical_wipe_done:
    ret


clear_screen5_vertical_pixel_column:
    ; E=byte column. Clears one 2-pixel SCREEN 5 column. Clobbers AF, BC, D, HL.
    ld hl, #0000
    ld d, 0
    add hl, de
    ld b, SCREEN5_PRESENTATION_VISIBLE_LINES
.vertical_row_loop:
    xor a
    push bc
    push de
    push hl
    ld bc, 1
    call FILVRM
    pop hl
    ld bc, SCREEN5_PRESENTATION_BYTES_PER_LINE
    add hl, bc
    pop de
    pop bc
    djnz .vertical_row_loop
    ret


clear_screen5_mirror_pixel_wipe:
    ; Wipes SCREEN 5 from both vertical edges inward. Clobbers AF, BC, DE, HL.
    ld e, 0
.mirror_column_loop:
    call clear_screen5_vertical_pixel_column
    ld a, SCREEN5_PRESENTATION_LAST_BYTE_COLUMN
    sub e
    ld e, a
    call clear_screen5_vertical_pixel_column
    ld a, SCREEN5_PRESENTATION_LAST_BYTE_COLUMN
    sub e
    inc a
    ld e, a
    halt
    cp SCREEN5_PRESENTATION_HALF_BYTES_PER_LINE
    jp c, .mirror_column_loop
    ret


clear_screen5_horizontal_pixel_wipe:
    ; Wipes SCREEN 5 in two horizontal scanlines per frame. Clobbers AF, BC, DE, HL.
    ld hl, #0000
    ld d, SCREEN5_PRESENTATION_VISIBLE_LINES
.horizontal_row_loop:
    xor a
    push de
    push hl
    ld bc, SCREEN5_PRESENTATION_BYTES_PER_LINE
    call FILVRM
    pop hl
    ld bc, SCREEN5_PRESENTATION_BYTES_PER_LINE
    add hl, bc
    pop de
    dec d
    jp z, .horizontal_wipe_done
    xor a
    push de
    push hl
    ld bc, SCREEN5_PRESENTATION_BYTES_PER_LINE
    call FILVRM
    pop hl
    ld bc, SCREEN5_PRESENTATION_BYTES_PER_LINE
    add hl, bc
    pop de
    dec d
    halt
    jp nz, .horizontal_row_loop
.horizontal_wipe_done:
    ret


clear_screen5_rect:
    ; HL=top-left VRAM byte, B=height, C=width. Clobbers AF, BC, DE, HL.
    ld a, b
    or a
    ret z
    ld a, c
    or a
    ret z
.rect_loop:
    push bc
    push hl
    ld b, 0
    xor a
    call FILVRM
    pop hl
    ld de, SCREEN5_PRESENTATION_BYTES_PER_LINE
    add hl, de
    pop bc
    djnz .rect_loop
    ret


clear_screen5_diagonal_pixel_wipe:
    ; Wipes SCREEN 5 in diagonal 8-line by 8-pixel bands. Clobbers AF, BC, DE, HL.
    ld hl, screen5_diagonal_pixel_wipe_table
.diagonal_table_loop:
    ld e, (hl)
    inc hl
    ld d, (hl)
    inc hl
    ld a, d
    cp #FF
    jp nz, .diagonal_rect_entry
    ld a, e
    cp #FE
    jp z, .diagonal_wait
    ret
.diagonal_wait:
    halt
    jp .diagonal_table_loop
.diagonal_rect_entry:
    push hl
    ld hl, #0000
    add hl, de
    pop de
    ld a, (de)
    inc de
    ld b, a
    ld a, (de)
    inc de
    ld c, a
    push de
    call clear_screen5_rect
    pop hl
    jp .diagonal_table_loop

